public sealed class Scheduler
{
    private const int MaxCalendarEntries = 20;
    private const int OvertimeCalendarThreshold = 10;
    private const int HighPriorityThreshold = 5;
    private const int UrgentPriorityThreshold = 8;
    private static readonly TimeSpan LongJobThreshold = TimeSpan.FromHours(8);

    public IReadOnlyList<string> PlaceJobs(IEnumerable<Job> jobs, IReadOnlyList<Resource> resources)
    {
        var placements = new List<string>();

        foreach (var job in jobs)
        {
            if (!HasRequiredSkill(job))
                continue;

            var chosen = FindBestResource(job, resources);
            placements.Add(FormatPlacement(job, chosen));
        }

        return placements;
    }

    private static bool HasRequiredSkill(Job job) =>
        !string.IsNullOrEmpty(job.RequiredSkill);

    private static Resource? FindBestResource(Job job, IEnumerable<Resource> resources) =>
        resources
            .Where(r => IsEligible(r, job))
            .OrderBy(r => r.Calendar.Count)
            .FirstOrDefault();

    private static bool IsEligible(Resource resource, Job job) =>
        resource.Skills.Contains(job.RequiredSkill) &&
        resource.Calendar.Count <= MaxCalendarEntries;

    private static string FormatPlacement(Job job, Resource? resource)
    {
        if (resource is null)
            return $"{job.Id}:UNPLACED";

        if (RequiresOvertime(job, resource))
            return $"{job.Id}:{resource.Name}:OT";

        if (job.Priority > UrgentPriorityThreshold)
            return $"{job.Id}:{resource.Name}:URGENT";

        return $"{job.Id}:{resource.Name}";
    }

