public sealed class VatResolver
{
    private static readonly IReadOnlyDictionary<string, decimal> Rates =
        new Dictionary<string, decimal>
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
            ["IE"] = 0.23m
        };

    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        if (net <= 0m) return 0m;

        var rate = GetBaseRate(countryCode);
        rate = ApplyAccountAdjustment(rate, account, net);
        rate = ApplyHighValueCap(rate, net);

        return net * rate;
    }

    private static decimal GetBaseRate(string countryCode) =>
        Rates.TryGetValue(countryCode, out var rate) ? rate : 0m;

    private static decimal ApplyAccountAdjustment(decimal rate, Account account, decimal net)
    {
        if (account.Kind == AccountKind.Government) return 0m;
        if (account.Kind == AccountKind.Business && net > 10000m) return rate * 0.5m;
        return rate;
    }

    private static decimal ApplyHighValueCap(decimal rate, decimal net) =>
        rate > 0m && net > 100000m ? Math.Min(rate, 0.15m) : rate;
}
