    var placements = new List<string>();

    foreach (var job in jobs)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill))
            continue;

        var chosen = ChooseResource(job, resources);
        placements.Add(chosen == null
            ? $"{job.Id}:UNPLACED"
            : FormatPlacement(job, chosen));
    }

    return placements;
}

private static Resource? ChooseResource(Job job, IEnumerable<Resource> resources)
{
    return resources
        .Where(r => r.Skills.Contains(job.RequiredSkill))
        .Where(r => r.Calendar.Count <= 20)
        .OrderBy(r => r.Calendar.Count)
        .FirstOrDefault();
}

private static string FormatPlacement(Job job, Resource resource)
{
    if (IsOvertime(job, resource))
        return $"{job.Id}:{resource.Name}:OT";

    if (job.Priority > 8)
        return $"{job.Id}:{resource.Name}:URGENT";

    return $"{job.Id}:{resource.Name}";
}

private static bool IsOvertime(Job job, Resource resource)
{
    return (job.Priority > 5 && resource.Calendar.Count > 10)
        || job.Duration.TotalHours > 8;
}
