```csharp
public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
{
    var plan = new List<string>();

    foreach (var item in items)
    {
        if (!ShouldReplenish(item, out var available))
            continue;

        var orderQty = ApplySeasonalAdjustment(CalculateOrderQuantity(item, available), season);
        if (orderQty <= 0 || string.IsNullOrEmpty(item.Sku))
            continue;

        var placed = supplier.PlaceOrder(item.Sku, orderQty);
        plan.Add(FormatPlanEntry(item.Sku, orderQty, placed));
    }

    return plan;
}

private static bool ShouldReplenish(StockItem item, out int available)
{
    available = item.OnHand - item.Reserved;
    return item.OnHand >= 0 && available <= item.ReorderPoint;
}

private static int CalculateOrderQuantity(StockItem item, int available)
{
    var deficit = item.ReorderPoint - available;
    if (deficit <= 0) return 0;
    if (deficit < 10) return 10;
    if (deficit < 100) return deficit;
    return deficit + 50;
}

private static int ApplySeasonalAdjustment(int orderQty, int season)
{
    if (season == 4 && orderQty > 0) return (int)(orderQty * 1.5);
    if (season == 1) return orderQty / 2;
    return orderQty;
}

private static string FormatPlanEntry(string sku, int orderQty, bool placed) =>
    !placed ? $"{sku}:FAILED" :
    orderQty > 200 ? $"{sku}:LARGE:{orderQty}" :
    $"{sku}:{orderQty}";
```

This reduces complexity in the main method and makes each business rule independently testable.

