public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
{
    var result = new List<string>();
    int remaining = GetAvailableStock(item);
    if (remaining <= 0)
        return result;

    foreach (var zone in warehouse.Zones.Where(IsUsableZone))
    {
        int place = CalculatePlacement(remaining, zone.Capacity);
        if (place <= 0)
            continue;

        result.Add(FormatAllocation(zone.Name, place));
        remaining -= place;

        if (remaining <= 0)
            break;
    }

    AddOverflowIfNeeded(result, remaining);
    return result;
}

private static int GetAvailableStock(StockItem item) => item.OnHand - item.Reserved;

private static bool IsUsableZone(Zone zone) =>
    zone.Capacity > 0 && !string.IsNullOrEmpty(zone.Name);

